# JADE Windows Security Analyzer
class JADEWindowsSecurity {
    [System.Collections.ArrayList]$SecurityEvents
    [hashtable]$SystemInfo
    [bool]$IsMonitoring

    JADEWindowsSecurity() {
        $this.SecurityEvents = [System.Collections.ArrayList]::new()
        $this.SystemInfo = @{}
        $this.IsMonitoring = $false
        $this.InitializeSystemInfo()
    }

    [void]InitializeSystemInfo() {
        $this.SystemInfo = @{
            ComputerName = $env:COMPUTERNAME
            OSVersion = (Get-WmiObject -Class Win32_OperatingSystem).Caption
            OSBuild = (Get-WmiObject -Class Win32_OperatingSystem).BuildNumber
            Architecture = (Get-WmiObject -Class Win32_OperatingSystem).OSArchitecture
            TotalRAM = [math]::Round((Get-WmiObject -Class Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 2)
            Processors = (Get-WmiObject -Class Win32_Processor).Name -join ", "
            Domain = (Get-WmiObject -Class Win32_ComputerSystem).Domain
            LastBootTime = (Get-WmiObject -Class Win32_OperatingSystem).ConvertToDateTime((Get-WmiObject -Class Win32_OperatingSystem).LastBootUpTime)
        }
    }

    # Analyze Windows Defender status
    [SecurityEvent]AnalyzeWindowsDefender() {
        try {
            $defenderStatus = Get-MpComputerStatus

            if (-not $defenderStatus.RealTimeProtectionEnabled) {
                return [SecurityEvent]::new(
                    "Windows Defender",
                    [ThreatLevel]::Critical,
                    "Real-time protection is disabled",
                    @{ Status = "Disabled"; LastScan = $defenderStatus.QuickScanStartTime },
                    "Enable Windows Defender real-time protection immediately"
                )
            }

            $daysSinceLastScan = ((Get-Date) - $defenderStatus.QuickScanStartTime).Days
            if ($daysSinceLastScan -gt 7) {
                return [SecurityEvent]::new(
                    "Windows Defender",
                    [ThreatLevel]::Medium,
                    "Last scan was more than 7 days ago",
                    @{ LastScan = $defenderStatus.QuickScanStartTime; DaysSince = $daysSinceLastScan },
                    "Run a full system scan"
                )
            }

            return [SecurityEvent]::new(
                "Windows Defender",
                [ThreatLevel]::Safe,
                "Windows Defender is active and up to date",
                @{ Status = "Active"; LastScan = $defenderStatus.QuickScanStartTime },
                "Continue regular scanning schedule"
            )

        } catch {
            return [SecurityEvent]::new(
                "Windows Defender",
                [ThreatLevel]::High,
                "Unable to query Windows Defender status",
                @{ Error = $_.Exception.Message },
                "Investigate Windows Defender service status"
            )
        }
    }

    # Check for suspicious processes
    [SecurityEvent[]]AnalyzeSuspiciousProcesses() {
        $events = @()
        $suspiciousProcesses = @()

        # Known malicious process names
        $maliciousNames = @(
            "keylogger", "backdoor", "trojan", "rootkit", "spyware",
            "cryptolocker", "ransomware", "miner", "coinminer",
            "svchost32", "winlogon32", "explorer32", "lsass32"
        )

        # Get all running processes
        $processes = Get-Process | Select-Object Name, Id, Path, CPU, WorkingSet, StartTime

        foreach ($process in $processes) {
            $threat = [ThreatLevel]::Safe
            $reasons = @()

            # Check for malicious names
            foreach ($malName in $maliciousNames) {
                if ($process.Name -like "*$malName*") {
                    $threat = [ThreatLevel]::Critical
                    $reasons += "Suspicious process name: $($process.Name)"
                }
            }

            # Check for processes without file paths (potential hollowing)
            if (-not $process.Path) {
                $threat = [ThreatLevel]::Medium
                $reasons += "Process running without file path"
            }

            # Check for high CPU usage
            if ($process.CPU -gt 80) {
                $threat = [ThreatLevel]::Medium
                $reasons += "High CPU usage: $($process.CPU)%"
            }

            # Check for excessive memory usage
            if ($process.WorkingSet -gt 1GB) {
                $threat = [ThreatLevel]::Low
                $reasons += "High memory usage: $([math]::Round($process.WorkingSet / 1MB, 2)) MB"
            }

            if ($threat -ne [ThreatLevel]::Safe) {
                $events += [SecurityEvent]::new(
                    "Process Analysis",
                    $threat,
                    "Suspicious process detected: $($process.Name)",
                    @{
                        ProcessName = $process.Name
                        ProcessId = $process.Id
                        Path = $process.Path
                        CPU = $process.CPU
                        Memory = $process.WorkingSet
                        Reasons = $reasons -join "; "
                    },
                    "Investigate process $($process.Name) (PID: $($process.Id))"
                )
            }
        }

        return $events
    }

    # Check system file integrity
    [SecurityEvent]CheckSystemIntegrity() {
        try {
            Write-Host "🔍 Running System File Checker (SFC)..."
            $sfcResult = sfc /verifyonly 2>&1

            if ($sfcResult -match "found corrupt files") {
                return [SecurityEvent]::new(
                    "System Integrity",
                    [ThreatLevel]::High,
                    "Corrupt system files detected",
                    @{ SFCOutput = $sfcResult -join "`n" },
                    "Run 'sfc /scannow' to repair corrupt files"
                )
            } elseif ($sfcResult -match "could not perform") {
                return [SecurityEvent]::new(
                    "System Integrity",
                    [ThreatLevel]::Medium,
                    "Unable to verify system file integrity",
                    @{ SFCOutput = $sfcResult -join "`n" },
                    "Check system permissions and disk health"
                )
            } else {
                return [SecurityEvent]::new(
                    "System Integrity",
                    [ThreatLevel]::Safe,
                    "System files integrity verified",
                    @{ SFCOutput = "No integrity violations found" },
                    "Continue regular integrity monitoring"
                )
            }
        } catch {
            return [SecurityEvent]::new(
                "System Integrity",
                [ThreatLevel]::Medium,
                "Failed to run system integrity check",
                @{ Error = $_.Exception.Message },
                "Manually verify system integrity"
            )
        }
    }

    # Analyze registry for suspicious entries
    [SecurityEvent[]]AnalyzeRegistry() {
        $events = @()

        # Check autostart locations
        $autostartKeys = @(
            "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
            "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce",
            "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
            "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"
        )

        foreach ($key in $autostartKeys) {
            try {
                $entries = Get-ItemProperty -Path $key -ErrorAction SilentlyContinue
                if ($entries) {
                    foreach ($property in $entries.PSObject.Properties) {
                        if ($property.Name -notmatch "^PS") {
                            $value = $property.Value
                            $threat = [ThreatLevel]::Safe

                            # Check for suspicious file locations
                            if ($value -match "\\temp\\|\\appdata\\local\\temp\\|\\users\\public\\") {
                                $threat = [ThreatLevel]::High
                            }

                            # Check for suspicious file extensions
                            if ($value -match "\.(bat|cmd|vbs|js|jar|scr)$") {
                                $threat = [ThreatLevel]::Medium
                            }

                            # Check for obfuscated commands
                            if ($value -match "powershell.*-enc|cmd.*\/c.*&") {
                                $threat = [ThreatLevel]::High
                            }

                            if ($threat -ne [ThreatLevel]::Safe) {
                                $events += [SecurityEvent]::new(
                                    "Registry Analysis",
                                    $threat,
                                    "Suspicious autostart entry found",
                                    @{
                                        RegistryKey = $key
                                        EntryName = $property.Name
                                        EntryValue = $value
                                    },
                                    "Review and remove suspicious autostart entry: $($property.Name)"
                                )
                            }
                        }
                    }
                }
            } catch {
                Write-Warning "Could not analyze registry key: $key"
            }
        }

        return $events
