    # Check network connections for suspicious activity
    [SecurityEvent[]]AnalyzeNetworkConnections() {
        $events = @()
        $suspiciousConnections = @()

        try {
            $connections = Get-NetTCPConnection | Where-Object { $_.State -eq "Established" }

            foreach ($conn in $connections) {
                $threat = [ThreatLevel]::Safe
                $reasons = @()

                # Check for connections to suspicious ports
                $suspiciousPorts = @(6667, 6668, 6669, 1337, 31337, 4444, 5555)
                if ($conn.RemotePort -in $suspiciousPorts) {
                    $threat = [ThreatLevel]::High
                    $reasons += "Connection to suspicious port: $($conn.RemotePort)"
                }

                # Check for connections to private IP ranges from internet-facing processes
                if ($conn.RemoteAddress -match "^(10\.|172\.1[6-9]\.|172\.2[0-9]\.|172\.3[0-1]\.|192\.168\.)") {
                    # This might be legitimate internal traffic
                } elseif ($conn.RemoteAddress -notmatch "^(127\.|::1)") {
                    # External connection - check process
                    try {
                        $process = Get-Process -Id $conn.OwningProcess -ErrorAction SilentlyContinue
                        if ($process -and $process.ProcessName -match "(cmd|powershell|rundll32|regsvr32)") {
                            $threat = [ThreatLevel]::Medium
                            $reasons += "Suspicious process with external connection: $($process.ProcessName)"
                        }
                    } catch {
                        # Could not get process info
                    }
                }

                if ($threat -ne [ThreatLevel]::Safe) {
                    $events += [SecurityEvent]::new(
                        "Network Analysis",
                        $threat,
                        "Suspicious network connection detected",
                        @{
                            LocalAddress = $conn.LocalAddress
                            LocalPort = $conn.LocalPort
                            RemoteAddress = $conn.RemoteAddress
                            RemotePort = $conn.RemotePort
                            ProcessId = $conn.OwningProcess
                            Reasons = $reasons -join "; "
                        },
                        "Investigate network connection and associated process"
                    )
                }
            }
        } catch {
            $events += [SecurityEvent]::new(
                "Network Analysis",
                [ThreatLevel]::Medium,
                "Failed to analyze network connections",
                @{ Error = $_.Exception.Message },
                "Manually check network connections using netstat"
            )
        }

        return $events
    }

    # Check Windows Update status
    [SecurityEvent]CheckWindowsUpdates() {
        try {
            $updateSession = New-Object -ComObject Microsoft.Update.Session
            $updateSearcher = $updateSession.CreateUpdateSearcher()
            $searchResult = $updateSearcher.Search("IsInstalled=0 and Type='Software'")

