                        CriticalUpdates = $criticalUpdates
                        SecurityUpdates = $securityUpdates
                    },
                    "Install critical Windows updates immediately"
                )
            } elseif ($securityUpdates -gt 0) {
                return [SecurityEvent]::new(
                    "Windows Updates",
                    [ThreatLevel]::Medium,
                    "$securityUpdates security updates pending",
                    @{
                        TotalUpdates = $searchResult.Updates.Count
                        SecurityUpdates = $securityUpdates
                    },
                    "Install security updates as soon as possible"
                )
            } else {
                return [SecurityEvent]::new(
                    "Windows Updates",
                    [ThreatLevel]::Safe,
                    "Windows is up to date",
                    @{ TotalUpdates = $searchResult.Updates.Count },
                    "Continue regular update monitoring"
                )
            }
        } catch {
            return [SecurityEvent]::new(
                "Windows Updates",
                [ThreatLevel]::Medium,
                "Unable to check Windows Update status",
                @{ Error = $_.Exception.Message },
                "Manually check Windows Update in Settings"
