    }

    # Run comprehensive security scan
    [hashtable]RunSecurityScan([bool]$FullScan = $false) {
        Write-Host "🚀 JADE Windows Security Analyzer - Starting Scan" -ForegroundColor Green
        Write-Host "🛡️  Comprehensive Windows security assessment" -ForegroundColor Green
        Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor Green

        $this.SecurityEvents.Clear()

        # Run security checks
        Write-Host "🔍 Analyzing Windows Defender status..." -ForegroundColor Yellow
        $this.SecurityEvents.Add($this.AnalyzeWindowsDefender()) | Out-Null

        Write-Host "🔍 Scanning for suspicious processes..." -ForegroundColor Yellow
        $processEvents = $this.AnalyzeSuspiciousProcesses()
        foreach ($event in $processEvents) {
            $this.SecurityEvents.Add($event) | Out-Null
        }

        if ($FullScan) {
            Write-Host "🔍 Checking system file integrity..." -ForegroundColor Yellow
            $this.SecurityEvents.Add($this.CheckSystemIntegrity()) | Out-Null
        }

        Write-Host "🔍 Analyzing registry entries..." -ForegroundColor Yellow
        $registryEvents = $this.AnalyzeRegistry()
        foreach ($event in $registryEvents) {
            $this.SecurityEvents.Add($event) | Out-Null
        }

