        $networkEvents = $this.AnalyzeNetworkConnections()
        foreach ($event in $networkEvents) {
            $this.SecurityEvents.Add($event) | Out-Null
        }

        Write-Host "🔍 Checking Windows Updates..." -ForegroundColor Yellow
        $this.SecurityEvents.Add($this.CheckWindowsUpdates()) | Out-Null

        return $this.GenerateSecurityReport()
