    # Generate security report
    [hashtable]GenerateSecurityReport() {
        $criticalEvents = $this.SecurityEvents | Where-Object { $_.ThreatLevel -eq [ThreatLevel]::Critical }
        $highEvents = $this.SecurityEvents | Where-Object { $_.ThreatLevel -eq [ThreatLevel]::High }
        $mediumEvents = $this.SecurityEvents | Where-Object { $_.ThreatLevel -eq [ThreatLevel]::Medium }
        $lowEvents = $this.SecurityEvents | Where-Object { $_.ThreatLevel -eq [ThreatLevel]::Low }

        $overallThreatLevel = if ($criticalEvents.Count -gt 0) { "CRITICAL" }
        elseif ($highEvents.Count -gt 0) { "HIGH" }
        elseif ($mediumEvents.Count -gt 0) { "MEDIUM" }
        elseif ($lowEvents.Count -gt 0) { "LOW" }
        else { "SAFE" }

        return @{
            Timestamp = Get-Date
            SystemInfo = $this.SystemInfo
            OverallThreatLevel = $overallThreatLevel
            EventCounts = @{
                Critical = $criticalEvents.Count
                High = $highEvents.Count
                Medium = $mediumEvents.Count
                Low = $lowEvents.Count
                Total = $this.SecurityEvents.Count
            }
            SecurityEvents = $this.SecurityEvents
            Recommendations = ($this.SecurityEvents | Where-Object { $_.ThreatLevel -ne [ThreatLevel]::Safe } | 
                             Select-Object -ExpandProperty Recommendation | Sort-Object -Unique)
        }
    }

    # Print security report
    [void]PrintSecurityReport([hashtable]$Report) {
        Write-Host "`n📊 WINDOWS SECURITY REPORT" -ForegroundColor Green
        Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor Green

        Write-Host "🖥️  System Information:" -ForegroundColor Cyan
        Write-Host "   Computer: $($Report.SystemInfo.ComputerName)" -ForegroundColor White
        Write-Host "   OS: $($Report.SystemInfo.OSVersion) (Build $($Report.SystemInfo.OSBuild))" -ForegroundColor White
        Write-Host "   Architecture: $($Report.SystemInfo.Architecture)" -ForegroundColor White
        Write-Host "   RAM: $($Report.SystemInfo.TotalRAM) GB" -ForegroundColor White
        Write-Host "   Last Boot: $($Report.SystemInfo.LastBootTime)" -ForegroundColor White

        Write-Host "`n🛡️  Security Assessment:" -ForegroundColor Cyan
        $threatColor = switch ($Report.OverallThreatLevel) {
            "CRITICAL" { "Red" }
            "HIGH" { "Red" }
            "MEDIUM" { "Yellow" }
            "LOW" { "Yellow" }
            "SAFE" { "Green" }
        }
        Write-Host "   Overall Threat Level: $($Report.OverallThreatLevel)" -ForegroundColor $threatColor

        Write-Host "`n📈 Event Summary:" -ForegroundColor Cyan
        Write-Host "   Critical: $($Report.EventCounts.Critical)" -ForegroundColor Red
        Write-Host "   High: $($Report.EventCounts.High)" -ForegroundColor Red
        Write-Host "   Medium: $($Report.EventCounts.Medium)" -ForegroundColor Yellow
        Write-Host "   Low: $($Report.EventCounts.Low)" -ForegroundColor Yellow
        Write-Host "   Total Events: $($Report.EventCounts.Total)" -ForegroundColor White

        if ($Report.SecurityEvents.Count -gt 0) {
            Write-Host "`n🚨 Security Events:" -ForegroundColor Cyan
            foreach ($event in ($Report.SecurityEvents | Where-Object { $_.ThreatLevel -ne [ThreatLevel]::Safe })) {
                $emoji = switch ($event.ThreatLevel) {
                    ([ThreatLevel]::Critical) { "💀" }
                    ([ThreatLevel]::High) { "🔴" }
                    ([ThreatLevel]::Medium) { "🟧" }
                    ([ThreatLevel]::Low) { "🟨" }
                }
                Write-Host "   $emoji $($event.ThreatLevel): $($event.Description)" -ForegroundColor White
                Write-Host "      Type: $($event.EventType)" -ForegroundColor Gray
                Write-Host "      Time: $($event.Timestamp)" -ForegroundColor Gray
            }
        }

        if ($Report.Recommendations.Count -gt 0) {
            Write-Host "`n💡 Security Recommendations:" -ForegroundColor Cyan
            foreach ($recommendation in $Report.Recommendations) {
                Write-Host "   • $recommendation" -ForegroundColor White
            }
        }

        Write-Host "`n✅ JADE Windows Security analysis completed!" -ForegroundColor Green
    }
}

# Main execution
function Main {
    try {
        $security = [JADEWindowsSecurity]::new()

        if ($QuickScan) {
            $report = $security.RunSecurityScan($false)
        } else {
            $report = $security.RunSecurityScan($FullScan)
        }

        $security.PrintSecurityReport($report)

        # Save report to log file
        if ($LogPath) {
            $reportJson = $report | ConvertTo-Json -Depth 5
            $reportJson | Out-File -FilePath $LogPath -Encoding UTF8
            Write-Host "`n📄 Report saved to: $LogPath" -ForegroundColor Green
        }

    } catch {
        Write-Error "❌ JADE Windows Security error: $($_.Exception.Message)"
        exit 1
    }
}

# Run the security analysis
Main
